<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {runtime} from './ipc';import type {TasksView,Method,WakeView} from './generated/protocol';
const busy=reactive(new Set<string>()),error=ref(''),details=ref<TasksView|null>(null),reason=ref('');
const evidence=reactive<Record<string,string>>({}),dates=reactive<Record<string,string>>({});
async function load(){error.value='';try{const r=await runtime.request({method:'tasks_read'});if('wakes' in r)details.value=r;}catch(e){error.value=String(e);}}
async function act(id:string,command:Method){busy.add(id);error.value='';try{await runtime.committed(command);await load();}catch(e){error.value=String(e);}finally{busy.delete(id);}}
function schedule(w:WakeView){const deadline_ms=new Date(dates[w.id]??'').getTime();if(!Number.isFinite(deadline_ms)){error.value='请选择有效时间';return;}return act(w.id,{method:'wake_schedule',params:{task:w.task,generation:w.task_generation,previous:w.generation,deadline_ms,reason:w.reason}});}
function dream(){return act('dream',{method:'dream_request',params:{request_id:crypto.randomUUID(),reason:reason.value}});}
onMounted(load);
</script>
<template><div class="panel"><p v-if="error" class="failure" role="alert">{{error}}</p><button @click="load">重新读取</button><p v-if="!runtime.state.snapshot?.tasks.length">还没有已提交任务。</p><article v-for="task in runtime.state.snapshot?.tasks" :key="task.id" class="resource-detail"><h3>{{task.id}}</h3><p>{{task.status}} · generation {{task.generation}}</p><p v-if="task.error" class="failure">{{task.error}}</p><button v-if="!['completed','failed','cancelled'].includes(task.status)" :disabled="busy.has(task.id)" @click="act(task.id,{method:'cancel',params:{task:task.id,generation:task.generation}})">{{busy.has(task.id)?'等待提交…':'停止此任务'}}</button><details v-for="tool in runtime.state.snapshot?.tools.filter(t=>t.task===task.id)" :key="tool.id"><summary>{{tool.name}} · {{tool.phase}}</summary><pre>{{tool.output}}</pre><small v-if="tool.truncated">已截断预览；完整记录仍保存在核心会话。</small><template v-if="tool.phase==='unknown'"><label>核实后的操作效果证据<textarea v-model="evidence[tool.id]"/></label><button :disabled="busy.has(tool.id)||!evidence[tool.id]?.trim()" @click="act(tool.id,{method:'resolve',params:{operation:tool.id,generation:task.generation,evidence:evidence[tool.id]!}})">提交证据</button><small>证据交回运行时判断后续行为；原工具不会自动重放。</small></template></details></article>
<h3>定时唤醒</h3><article v-for="wake in details?.wakes" :key="`${wake.id}/${wake.generation}`" class="resource-detail"><p>{{wake.task}} · {{wake.phase}} · {{new Date(wake.deadline_ms).toLocaleString()}}</p><p>{{wake.reason}}</p><template v-if="wake.phase!=='cancelled'&&!wake.delivered"><label>改期<input v-model="dates[wake.id]" type="datetime-local"/></label><div class="actions"><button :disabled="busy.has(wake.id)" @click="schedule(wake)">保存改期</button><button :disabled="busy.has(wake.id)" @click="act(wake.id,{method:'wake_cancel',params:{id:wake.id,generation:wake.generation}})">取消唤醒</button></div></template></article>
<h3>Dream</h3><label>请求原因<textarea v-model="reason"/></label><div class="actions"><button :disabled="busy.has('dream')||!reason.trim()" @click="dream">请求 Dream</button><button :disabled="busy.has('dream')||!details" @click="details&&act('dream',{method:'dream_cancel',params:{revision:details.revision,dream_revision:details.dream_revision}})">取消 Dream</button></div><p v-for="request in details?.dreams" :key="request.id">{{request.id}} · {{request.finished?'已结束':'待处理 / 运行中'}}<small>{{request.reasons.join(' · ')}}</small></p><details v-for="job in details?.jobs" :key="job.id"><summary>{{job.id}} · {{job.target}} · {{job.phase}}</summary><pre>{{job.result}}</pre><p class="failure">{{job.error}}</p><p v-if="job.skipped">已解除等待，验证作业独立运行。</p><button v-else :disabled="busy.has(job.id)||details?.dream_revision==null" @click="act(job.id,{method:'dream_detach',params:{job:job.id,revision:details!.dream_revision!}})">解除等待</button><button :disabled="busy.has(job.id)||details?.dream_revision==null" @click="act(job.id,{method:'dream_job_cancel',params:{job:job.id,revision:details!.dream_revision!}})">取消此验证作业</button></details>
</div></template>
